package com.example.e2e.messaging;

import com.example.e2e.logging.Outcomes;

/**
 * Metric names of com.example.e2e.messaging, in one place: call sites call a member here and never name a metric.
 * Generated by logast (metrics.catalog). Rename or document members freely; logast keeps them and adds new
 * ones at the end.
 */
// logast:metrics-catalog
public final class MessagingMetrics {
    private MessagingMetrics() {
    }

    /** Observation (timer and span) name. */
    public static final String COUPON_MESSAGES_ON_BATCH = "coupon-messages.on-batch";

    /** coupon.messages{outcome="completed"} +1. */
    public static void couponMessagesCompleted() {
        Outcomes.count("coupon.messages", "completed");
    }

    /** Registers this catalog's counters at 0 when the application has started: a series exists before the first event. */
    @org.springframework.stereotype.Component
    static final class Registration implements org.springframework.beans.factory.SmartInitializingSingleton {
        @Override
        public void afterSingletonsInstantiated() {
            Outcomes.register("coupon.messages", "completed");
        }
    }
}
